INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-070', 'RP', 'P1', 'OPEN', 'research-batch', 'base_parameters parameter_id 12 (TERM-091); terms TERM-090, TERM-092', 'REST-LANDING LIMITS STATED AS RISE HAVE NO PARAMETER. Parameter 12 is the horizontal run between landings (TERM-091), and its scope note keeps it distinct from the vertical dimension. Admitted codes state the same rest-landing requirement as a vertical figure instead of, or beside, a run: REF-01012 TEK17 12-16(2) (rest plane per height difference, no landing run stated), REF-00987 ADA 405.6 (rise for any ramp run), REF-00992 para 1.26(c) and Table 1''s ''Maximum rise'' column, REF-00995 Art. 19 para 4. A rise cannot be filed under parameter 12 without mixing two dimensions in one value space, and a run cannot be inferred from a rise without the gradient. Figures are not copied here (rule 5); they are in the persisted payloads (retrieval-log/session_2026-10-30-rest-landing-parameter/) at those clauses. Run, going and landing figures for other codes already sit under parameter 3 inside claimed_unit strings (derive: select extraction_id, ref_id, claimed_unit from source_value_extractions where parameter_id = 3 and (claimed_unit like ''%run%'' or claimed_unit like ''%going%'' or claimed_unit like ''%projection%'' or claimed_unit like ''%landing%'')); whoever settles the rise question also decides whether those are re-pointed at parameter 12 by new rows (committed rows are immutable, rule 3). OPTIONS, the owner''s call because it fixes what a determination is keyed on: (a) promote TERM-090 level difference. Weakness: TERM-090 is the TOTAL rise a ramp must overcome, and Art. 19 para 1''s bands (parameter 3 rows for REF-00995) already use it as total rise, so a per-flight rise would share a key with the total. (b) mint a term for the rise of a single flight between landings, distinct from the total (RECOMMENDED: the quantity differs, so it is not the near-duplicate the parameter 3 note warns of). (c) one rest-landing parameter with two expressions (needs a unit-class column the schema does not have). The owner''s 2026-10-30 approval (D18/E7) is not recorded in references/project-standards.md; record it when this is settled.', '2026-10-30 22:02', 'session_2026-10-30-rest-landing-parameter', '2026-10-30 22:02', 'session_2026-10-30-rest-landing-parameter', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-071', 'RP', 'P2', 'OPEN', 'research-batch', 'source_value_extractions parameter_id 12; terms TERM-092 intermediate landing', 'REST-LANDING SPACING IS READ FOR A FEW CODES; THE COMPLEMENT QUERY OVER-INCLUDES. Derive what parameter 12 holds: select distinct ref_id, jurisdiction from source_value_extractions where parameter_id = 12. Sources read this session without a parameter-12 row: REF-00996 (restates Art. 19 of REF-00995 by level-difference band, so not independent of it), REF-01012 and REF-00987 (rise-stated; see the rise gap). The earlier ramp-session readings for Singapore, Japan, New Zealand and the United States came from secondary sources and are UNVERIFIED: no Singapore source is in evidence_sources (batch 23''s attempts at the bca.gov.sg host returned 403 or empty), and the Japanese (REF-00990, REF-00991) and New Zealand (REF-01016) texts were not opened here. A query for ''not yet read'' (tier 5-6 sources with no parameter-12 row) lists sources that are merely unextracted; sources already read for another parameter may hold a run limit in the parameter 3 claimed_unit strings named in the rise gap. TERM-092 intermediate landing (the landing''s own dimensions) is neither a parameter nor declined; decide with the rise question. R16 note: observed_terms for REF-00988 holds no ''Podest'' sighting.', '2026-10-30 22:02', 'session_2026-10-30-rest-landing-parameter', '2026-10-30 22:02', 'session_2026-10-30-rest-landing-parameter', NULL, NULL, NULL, NULL, NULL);
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-072', 'ST', 'P3', 'OPEN', 'research-batch', 'scripts/assess/assess_cell.py NOTATION_FAMILIES; source_value_extractions parameter_id 12', 'COMPOSITION OF PARAMETER 12 REFUSES MIXED LENGTH UNITS. assess_cell.NOTATION_FAMILIES holds only the gradient family, so compose_value over parameter 12''s governing claims returns NULL with ''stated in different units'' as soon as one source states centimetres and another metres, and the only value that composes drops the gentlest figure. Reproduce: python3 -I -c with compose_value(con, [{''role'':''governing'',''extraction_id'':e} for e in <ids of parameter 12 rows>], ''lower_is_better''). Not repaired here: a tooling change ships in its own PR (rule 10). The rows keep the unit each source states.', '2026-10-30 22:02', 'session_2026-10-30-rest-landing-parameter', '2026-10-30 22:02', 'session_2026-10-30-rest-landing-parameter', NULL, NULL, NULL, NULL, NULL);

-- base_parameters: 0 insert(s), 1 update(s)
UPDATE "base_parameters" SET "notes" = 'Promoted from the base vocabulary on the owner''s direction of 2026-10-09 (populate the parameter table from the existing terms registry). Judged a measurable design quantity by the session; no source adjudication behind it. Direction left unset until an admitted source states which way is better for a disabled person. || ANNOTATED 2026-10-30 by session_2026-10-30-rest-landing-parameter: Two sentences above no longer hold. ''Direction left unset until an admitted source states which way is better'' is superseded: accessibility_direction and direction_rationale now carry it. ''no source adjudication behind it'' was false when written (derive: select outcome from term_adjudications where term_id = ''TERM-091''; GAP-067). The owner''s 2026-10-30 hypothesis that the problem on a ramp is the lack of a rest landing, and the approval to make landing spacing a headline parameter, are recorded as owner decision D18 and row E7 in workplan/2026-10-30-ramp-spec-pages/RENDER-DECISIONS-AND-PIPELINE.md and in HANDOFF.md section 3; E7 asks that the approval be confirmed, and it is not yet in references/project-standards.md. The maximum run between rests is this parameter''s run, so no second parameter was minted (rule 5). The vertical expression is a separate open question (the rise gap).', "updated_at" = '2026-10-30 22:02', "updated_by_session" = 'session_2026-10-30-rest-landing-parameter', "direction_rationale" = 'A shorter permitted run between landings is more accessible for a disabled person: the admitted sources state the need a landing serves, and none states a longer unbroken run as better. REF-00992 (Approved Document M, para 1.22): ''Some people need to be able to stop frequently; for instance to regain strength or breath, or to ease pain.'' REF-00995 (Flemish decree of 5 June 2009, explanatory memorandum to Article 19): a landing is required per 50 cm of level difference or 10 m of ramp ''om de nodige rustpunten te voorzien door te vermijden dat een helling te lang aanhoudt'' (to provide the necessary rest points by preventing a ramp continuing too long). REF-00996 states the same mechanism (''zodat voldoende rustpunten ingebouwd worden'') but names Article 19 of that decree as its regulation, so it restates REF-00995 and is not a third independent source. Derived from those statements, not adjudicated; no source states the direction as a rule about the run limit itself. NOT contested: no admitted source identifies a population for whom a longer unbroken run is better. The codes pair a shorter run with a steeper permitted gradient (REF-00992 Table 1); that trade belongs to the gradient parameter (3, lower_is_better), not to this one.', "accessibility_direction" = 'lower_is_better' WHERE "parameter_id" = 12;

