INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (115, 'REF-00995', NULL, 3, 'MOB', NULL, NULL, NULL, 'BE', NULL, 'numerical', '4', '%', 'De bepaling is slechts van toepassing op toegangspaden met een helling groter dan 4 %', 'Besluit van de Vlaamse Regering van 5 juni 2009, nota van toelichting bij Artikel 19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 'section', NULL, NULL, '19', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'explanatory memorandum to Article 19; the decree text of para 4 says ''meer dan vier procent''', 'full-read', 'preliminary', NULL, 'The slope above which Article 19 applies and para 4 requires an intermediate landing; filed as the condition the run-length row for parameter 12 stands on. Read once from the codex page re-retrieved this session. Provisional. Lens MOB follows the corpus convention for code values (derive: select identity_code, needs_code, count(*) from source_value_extractions group by 1,2) and is UNREVIEWED; the source names wheelchair users. No ICF or access-need tag is assigned.', '2026-10-30 22:02', 'session_2026-10-30-rest-landing-parameter', '2026-10-30 22:02', 'session_